<template><div class="app-container info-page"><div class="page-head"><div><h2>招领信息</h2><p>查看用户发布的招领记录并维护图片搜索索引</p></div><el-button type="primary" plain icon="el-icon-refresh" :loading="syncing" @click="syncImages">全量同步图片</el-button></div><div class="filter-card"><el-form :inline="true" :model="query" size="small"><el-form-item label="物品"><el-input v-model.trim="query.itemName" clearable placeholder="物品名称" @keyup.enter.native="search" /></el-form-item><el-form-item label="地点"><el-input v-model.trim="query.occurPlace" clearable placeholder="拾取地点" @keyup.enter.native="search" /></el-form-item><el-form-item label="审核状态"><el-select v-model="query.auditStatus" clearable placeholder="全部"><el-option label="待审核" :value="0"/><el-option label="已通过" :value="1"/><el-option label="已驳回" :value="2"/></el-select></el-form-item><el-form-item label="信息状态"><el-select v-model="query.publishStatus" clearable placeholder="全部"><el-option label="已下架" :value="0"/><el-option label="待认领" :value="1"/><el-option label="认领中" :value="2"/><el-option label="已归还" :value="3"/></el-select></el-form-item><el-form-item><el-button @click="reset">重置</el-button><el-button type="primary" icon="el-icon-search" @click="search">查询</el-button></el-form-item></el-form></div><div class="table-card"><el-table v-loading="loading" :data="items"><el-table-column label="物品信息" min-width="260"><template slot-scope="{row}"><div class="item-cell"><div class="cover"><image-preview v-if="row.coverImage" :src="row.coverImage" width="66px" height="66px"/><i v-else class="el-icon-picture-outline"/></div><div><strong>{{row.itemName}}</strong><small>{{row.infoNo}}</small><el-tag size="mini" type="success">招领</el-tag></div></div></template></el-table-column><el-table-column prop="categoryName" label="分类" width="110" align="center"/><el-table-column label="拾取地点 / 时间" min-width="200"><template slot-scope="{row}"><div class="location"><span><i class="el-icon-location-outline"/> {{row.occurPlace||'未填写'}}</span><small>{{formatDate(row.occurDate)}}</small></div></template></el-table-column><el-table-column prop="realName" label="发布人" width="100" align="center"/><el-table-column label="审核" width="100" align="center"><template slot-scope="{row}"><el-tag size="small" :type="auditType(row.auditStatus)">{{auditText(row.auditStatus)}}</el-tag></template></el-table-column><el-table-column label="状态" width="100" align="center"><template slot-scope="{row}"><el-tag size="small" :type="publishType(row.publishStatus)">{{publishText(row.publishStatus)}}</el-tag></template></el-table-column><el-table-column prop="createTime" label="发布时间" width="165" align="center"/><el-table-column label="操作" width="90" fixed="right" align="center"><template slot-scope="{row}"><el-button type="text" @click="detailRow(row)">详情</el-button></template></el-table-column></el-table></div><pagination :total="total" :current-page.sync="query.current" :page-size.sync="query.size" :page-sizes="[10,20,50]" @pagination="load"/><el-dialog title="招领信息详情" :visible.sync="detailOpen" width="760px" append-to-body><div v-loading="detailLoading"><div class="detail-hero"><image-preview v-if="detail.coverImage" :src="detail.coverImage" width="110px" height="110px"/><div><h3>{{detail.itemName||'-'}}</h3><p>{{detail.infoNo}}</p><el-tag type="success" size="small">招领</el-tag><el-tag :type="auditType(detail.auditStatus)" size="small">{{auditText(detail.auditStatus)}}</el-tag></div></div><el-descriptions :column="2" border><el-descriptions-item label="分类">{{detail.categoryName||'-'}}</el-descriptions-item><el-descriptions-item label="发布人">{{detail.realName||'-'}}</el-descriptions-item><el-descriptions-item label="拾取地点">{{detail.occurPlace||'-'}}</el-descriptions-item><el-descriptions-item label="拾取时间">{{detail.occurDate||'-'}}</el-descriptions-item><el-descriptions-item label="联系人">{{detail.contactName||'-'}}</el-descriptions-item><el-descriptions-item label="联系电话">{{detail.contactPhone||'-'}}</el-descriptions-item><el-descriptions-item label="物品特征" :span="2">{{detail.itemFeatures||'-'}}</el-descriptions-item><el-descriptions-item label="描述" :span="2">{{detail.description||'-'}}</el-descriptions-item><el-descriptions-item label="领取方式" :span="2">{{detail.claimMethod||'-'}}</el-descriptions-item><el-descriptions-item label="全部图片" :span="2"><image-preview v-if="detail.itemImages" :src="detail.itemImages" width="82px" height="82px"/><span v-else>暂无图片</span></el-descriptions-item></el-descriptions></div><div slot="footer"><el-button @click="detailOpen=false">关闭</el-button></div></el-dialog></div></template>
<script>import Pagination from '@/components/Pagination';import ImagePreview from '@/components/ImagePreview';import{pageLostFoundInfo,getLostFoundInfoById,rebuildLostFoundImageIndex}from'@/api/lost_found_info';export default{name:'ClaimInfoManage',components:{Pagination,ImagePreview},data(){return{loading:false,syncing:false,detailOpen:false,detailLoading:false,items:[],total:0,detail:{},query:{current:1,size:10,infoType:2,itemName:null,occurPlace:null,auditStatus:null,publishStatus:null}}},created(){this.load()},methods:{async load(){this.loading=true;try{const{current,size,...data}=this.query;const r=await pageLostFoundInfo(current,size,data);this.items=r.data.records||[];this.total=Number(r.data.total)||0}finally{this.loading=false}},search(){this.query.current=1;this.load()},reset(){this.query={current:1,size:this.query.size||10,infoType:2,itemName:null,occurPlace:null,auditStatus:null,publishStatus:null};this.load()},detailRow(row){this.detailOpen=true;this.detailLoading=true;getLostFoundInfoById(row.id).then(r=>{this.detail=r.data||row}).finally(()=>{this.detailLoading=false})},syncImages(){this.$confirm('将全部招领图片重新向量化并同步到图片搜索服务，是否继续？','全量同步',{type:'warning'}).then(async()=>{this.syncing=true;try{const r=await rebuildLostFoundImageIndex(2);this.$message.success(`同步完成，成功处理 ${r.data||0} 条`)}finally{this.syncing=false}}).catch(()=>{})},auditText(v){return({0:'待审核',1:'已通过',2:'已驳回'})[v]||'未知'},auditType(v){return({0:'warning',1:'success',2:'danger'})[v]||'info'},publishText(v){return({0:'已下架',1:'待认领',2:'认领中',3:'已归还'})[v]||'未知'},publishType(v){return({0:'info',1:'warning',2:'primary',3:'success'})[v]||'info'},formatDate(v){return v?String(v).slice(0,16):'时间待补充'}}}</script>
<style scoped>.info-page{padding:24px}.page-head{display:flex;align-items:center;justify-content:space-between;margin-bottom:20px}.page-head h2{margin:0;color:#263b50;font-size:24px}.page-head p{margin:7px 0 0;color:#8998a8}.filter-card,.table-card{border:1px solid #e5edf4;border-radius:14px;background:#fff}.filter-card{margin-bottom:18px;padding:18px 18px 0}.table-card{overflow:hidden}.item-cell{display:flex;align-items:center;gap:12px}.cover{display:flex;width:66px;height:66px;align-items:center;justify-content:center;overflow:hidden;flex:none;border-radius:10px;color:#9badbd;background:#eef3f7;font-size:24px}.item-cell strong,.item-cell small{display:block}.item-cell strong{margin-bottom:5px;color:#263b50}.item-cell small{margin-bottom:6px;color:#93a1af;font-size:11px}.location span,.location small{display:block}.location span{color:#536a80}.location small{margin-top:7px;color:#9aa8b6}.detail-hero{display:flex;align-items:center;gap:18px;margin-bottom:18px}.detail-hero h3{margin:0 0 7px;color:#263b50;font-size:21px}.detail-hero p{margin:0 0 9px;color:#8b9aa9}.detail-hero .el-tag{margin-right:7px}</style>
